function validate([n, sick]) {
  if (!Number.isInteger(n) || n < 2 || n > 100000) return 'n is an integer from 2 to 10^5.';
  if (!Array.isArray(sick) || sick.length < 1 || sick.length > n - 1) return 'sick has between 1 and n - 1 positions.';
  for (let i = 0; i < sick.length; i++) {
    if (!Number.isInteger(sick[i]) || sick[i] < 0 || sick[i] > n - 1) return 'Each position in sick is between 0 and n - 1.';
    if (i > 0 && sick[i] <= sick[i - 1]) return 'sick must be strictly increasing.';
  }
  return null;
}

