function numberOfSequence(n, sick) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) {
        result = result * base % MOD;
      }
      base = base * base % MOD;
      exponent /= 2n;
    }
    return result;
  };

  const fact = [1n];
  for (let k = 1; k <= n; k++) {
    fact.push(fact[k - 1] * BigInt(k) % MOD);
  }

  const m = sick.length;
  let denominator = fact[sick[0]] * fact[n - 1 - sick[m - 1]] % MOD;
  let doubling = 0;
  for (let i = 1; i < m; i++) {
    const gap = sick[i] - sick[i - 1] - 1;
    denominator = denominator * fact[gap] % MOD;
    if (gap > 0) {
      doubling += gap - 1;
    }
  }

  const healthy = n - m;
  const orders = fact[healthy] * power(denominator, MOD - 2n) % MOD;
  return Number(orders * power(2n, BigInt(doubling)) % MOD);
}

