function numberOfSequence(n, sick) {
  const MOD = 1000000007;
  const startSick = new Array(n).fill(false);
  for (const s of sick) startSick[s] = true;
  const healthy = [];
  for (let p = 0; p < n; p++) if (!startSick[p]) healthy.push(p);
  const h = healthy.length;
  const bit = new Array(n).fill(-1);
  healthy.forEach((p, k) => { bit[p] = k; });
  // ways[mask] = number of ways to finish when the healthy people in mask are already infected.
  const ways = new Array(1 << h).fill(0);
  ways[(1 << h) - 1] = 1;
  for (let mask = (1 << h) - 2; mask >= 0; mask--) {
    const infected = p => p >= 0 && p < n && (startSick[p] || ((mask >> bit[p]) & 1) === 1);
    let total = 0;
    for (let k = 0; k < h; k++) {
      if ((mask >> k) & 1) continue;
      const p = healthy[k];
      if (infected(p - 1) || infected(p + 1)) total = (total + ways[mask | (1 << k)]) % MOD;
    }
    ways[mask] = total;
  }
  return ways[0];
}

