function generate(rand, size) {
  if (size === 'small') {
    for (;;) {
      const n = 2 + Math.floor(rand() * 11);
      const chance = 0.15 + rand() * 0.6;
      const sick = [];
      for (let p = 0; p < n; p++) if (rand() < chance) sick.push(p);
      if (sick.length >= 1 && sick.length <= n - 1) return [n, sick];
    }
  }
  const n = 50000 + Math.floor(rand() * 50001);
  const m = rand() < 0.3 ? 1 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 2000);
  const chosen = new Set();
  while (chosen.size < m) chosen.add(Math.floor(rand() * n));
  const sick = [...chosen].sort((a, b) => a - b);
  return [n, sick];
}
